"use client";

import {
  CaretRightIcon,
  ChartLineUpIcon,
  CheckIcon,
  FigmaLogoIcon,
  GithubLogoIcon,
  GoogleLogoIcon,
  KanbanIcon,
  LightningIcon,
  MegaphoneIcon,
  NotionLogoIcon,
  PlugsConnectedIcon,
  PulseIcon,
  SlackLogoIcon,
} from "@phosphor-icons/react";
import { useRef, useState } from "react";
import { Alert } from "../../../components/vip-ui/alert";
import { Badge } from "../../../components/vip-ui/badge";
import { Button } from "../../../components/vip-ui/button";
import {
  DescriptionDetail,
  DescriptionList,
  DescriptionTerm,
} from "../../../components/vip-ui/description-list";
import {
  EmptyState,
  EmptyStateActions,
  EmptyStateDescription,
  EmptyStateIcon,
  EmptyStateTitle,
} from "../../../components/vip-ui/empty-state";
import { GridList, GridListItem } from "../../../components/vip-ui/grid-list";
import { SearchField } from "../../../components/vip-ui/search-field";
import {
  Sheet,
  SheetBody,
  SheetClose,
  SheetDescription,
  SheetFooter,
  SheetHeader,
  SheetTitle,
} from "../../../components/vip-ui/sheet";
import { Switch } from "../../../components/vip-ui/switch";
import { Tab, TabList, TabPanel, Tabs } from "../../../components/vip-ui/tabs";
import { showToast } from "../../../components/vip-ui/toast";
import { SettingsShell } from "./settings-shell";

const categories = [
  { id: "all", label: "All" },
  { id: "analytics", label: "Analytics" },
  { id: "communication", label: "Communication" },
  { id: "developer", label: "Developer" },
  { id: "design", label: "Design" },
] as const;

type Category = (typeof categories)[number]["id"];

interface App {
  id: string;
  name: string;
  publisher: string;
  category: Exclude<Category, "all">;
  tagline: string;
  description: string;
  permissions: string[];
  connected: boolean;
  beta?: boolean;
  needsAttention?: boolean;
  connectedBy?: string;
  connectedOn?: string;
  lastSync?: string;
  icon: typeof SlackLogoIcon;
}

const initialApps: App[] = [
  {
    id: "slack",
    name: "Slack",
    publisher: "Salesforce, Inc.",
    category: "communication",
    tagline: "Alerts and mentions",
    description:
      "Send Kestrel alerts to team channels and mention people from a customer record.",
    permissions: [
      "Post messages to selected channels",
      "Read channel names and members",
    ],
    connected: true,
    connectedBy: "Nadia Okafor",
    connectedOn: "Sep 18, 2026",
    lastSync: "2 min ago",
    icon: SlackLogoIcon,
  },
  {
    id: "github",
    name: "GitHub",
    publisher: "GitHub, Inc.",
    category: "developer",
    tagline: "Deploys and pull requests",
    description:
      "Link deploys and pull requests to the release that includes them.",
    permissions: ["Read repositories and deployments", "Write commit statuses"],
    connected: true,
    connectedBy: "Leo Park",
    connectedOn: "Aug 4, 2026",
    lastSync: "12 min ago",
    icon: GithubLogoIcon,
  },
  {
    id: "figma",
    name: "Figma",
    publisher: "Figma, Inc.",
    category: "design",
    tagline: "Design previews",
    description: "Show live design previews and open a frame in Figma.",
    permissions: ["Read file names and previews", "Read comments"],
    connected: true,
    needsAttention: true,
    connectedBy: "Nadia Okafor",
    connectedOn: "Oct 9, 2026",
    lastSync: "Paused",
    icon: FigmaLogoIcon,
  },
  {
    id: "notion",
    name: "Notion",
    publisher: "Notion Labs, Inc.",
    category: "communication",
    tagline: "Shared reports",
    description: "Publish weekly reports to a Notion database.",
    permissions: ["Read selected pages", "Create pages in one database"],
    connected: true,
    connectedBy: "Ana Souza",
    connectedOn: "Sep 30, 2026",
    lastSync: "1 h ago",
    icon: NotionLogoIcon,
  },
  {
    id: "segment",
    name: "Segment",
    publisher: "Twilio, Inc.",
    category: "analytics",
    tagline: "Product events",
    description: "Send product events to Kestrel and map them to metrics.",
    permissions: ["Read event sources", "Write destination settings"],
    connected: true,
    connectedBy: "Nadia Okafor",
    connectedOn: "Oct 2, 2026",
    lastSync: "4 min ago",
    icon: ChartLineUpIcon,
  },
  {
    id: "hubspot",
    name: "HubSpot",
    publisher: "HubSpot, Inc.",
    category: "analytics",
    tagline: "Companies and deals",
    description: "Sync companies and deal stages with Kestrel accounts.",
    permissions: ["Read contacts and companies", "Read deal stages"],
    connected: false,
    icon: MegaphoneIcon,
  },
  {
    id: "datadog",
    name: "Datadog",
    publisher: "Datadog, Inc.",
    category: "analytics",
    tagline: "Usage metrics",
    description: "Send Kestrel usage metrics to Datadog.",
    permissions: ["Write metrics", "Read monitors"],
    connected: true,
    connectedBy: "Leo Park",
    connectedOn: "Sep 12, 2026",
    lastSync: "6 min ago",
    icon: PulseIcon,
  },
  {
    id: "zapier",
    name: "Zapier",
    publisher: "Zapier, Inc.",
    category: "developer",
    tagline: "Task automation",
    description: "Start a task when a customer record changes.",
    permissions: ["Read and write selected records"],
    connected: true,
    beta: true,
    connectedBy: "Kwame Mensah",
    connectedOn: "Oct 21, 2026",
    lastSync: "18 min ago",
    icon: LightningIcon,
  },
  {
    id: "linear",
    name: "Linear",
    publisher: "Linear Orbit, Inc.",
    category: "developer",
    tagline: "Issue sync",
    description:
      "Create Linear issues from feedback and keep the status in sync.",
    permissions: ["Read teams", "Create issues"],
    connected: false,
    beta: true,
    icon: KanbanIcon,
  },
  {
    id: "google-analytics",
    name: "Google Analytics",
    publisher: "Google LLC",
    category: "analytics",
    tagline: "Site traffic",
    description: "Compare Kestrel use with site traffic and campaigns.",
    permissions: ["Read property reports"],
    connected: false,
    icon: GoogleLogoIcon,
  },
];

function categoryLabel(category: App["category"]) {
  return categories.find((item) => item.id === category)?.label ?? category;
}

export function IntegrationsSettings() {
  const [apps, setApps] = useState(initialApps);
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<Category>("all");
  const [figmaAlert, setFigmaAlert] = useState(true);
  const [sheetId, setSheetId] = useState<string | null>(null);
  const [sheetOpen, setSheetOpen] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);

  const terms = query.trim().toLowerCase().split(/\s+/).filter(Boolean);
  const shown = apps.filter((app) => {
    if (category !== "all" && app.category !== category) return false;
    if (terms.length === 0) return true;
    const text = [app.name, app.tagline, app.description, app.publisher]
      .join(" ")
      .toLowerCase();
    return terms.every((term) => text.includes(term));
  });
  const sheetApp = apps.find((app) => app.id === sheetId) ?? null;

  function setConnected(id: string, connected: boolean) {
    const app = apps.find((item) => item.id === id);
    setApps((current) =>
      current.map((item) =>
        item.id === id
          ? {
              ...item,
              connected,
              needsAttention: connected ? false : item.needsAttention,
              lastSync: connected ? "Just now" : "Paused",
            }
          : item,
      ),
    );
    if (connected) {
      setFigmaAlert((visible) => (id === "figma" ? false : visible));
    }
    if (app) {
      showToast({
        title: `${app.name} is ${connected ? "connected" : "disconnected"}`,
        description: connected
          ? "Kestrel can now share data with this app."
          : "Kestrel stops sending data to this app.",
        variant: connected ? "success" : "warning",
      });
    }
  }

  function reconnect(id: string) {
    const app = apps.find((item) => item.id === id);
    setApps((current) =>
      current.map((item) =>
        item.id === id
          ? {
              ...item,
              connected: true,
              needsAttention: false,
              lastSync: "Just now",
            }
          : item,
      ),
    );
    setFigmaAlert(false);
    showToast({
      title: `${app?.name ?? "The app"} is reconnected`,
      description: "Sync starts again in a few seconds.",
      variant: "success",
    });
    if (!sheetOpen) {
      requestAnimationFrame(() =>
        searchRef.current?.querySelector("input")?.focus(),
      );
    }
  }

  function clearSearch() {
    setQuery("");
    requestAnimationFrame(() =>
      searchRef.current?.querySelector("input")?.focus(),
    );
  }

  return (
    <SettingsShell
      current="integrations"
      title="Connected apps"
      description="Connect Kestrel to the tools your team uses."
    >
      <div className="grid gap-5">
        <h2 className="sr-only">App directory</h2>
        {figmaAlert && (
          <Alert
            variant="warning"
            title="Figma needs a new sign-in"
            onDismiss={() => {
              setFigmaAlert(false);
              requestAnimationFrame(() =>
                searchRef.current?.querySelector("input")?.focus(),
              );
            }}
            action={
              <Button
                size="sm"
                variant="outline"
                onPress={() => reconnect("figma")}
              >
                Reconnect
              </Button>
            }
          >
            The access token ended on Oct 30, 2026. Design previews are paused.
          </Alert>
        )}

        <div className="grid gap-4">
          <Tabs
            selectedKey={category}
            onSelectionChange={(key) => setCategory(key as Category)}
          >
            <div className="flex flex-col gap-3 md:flex-row md:items-end md:justify-between">
              <TabList aria-label="App category">
                {categories.map((item) => (
                  <Tab key={item.id} id={item.id} className="px-3">
                    {item.label}
                  </Tab>
                ))}
              </TabList>
              <div
                ref={searchRef}
                className="w-full md:w-44 md:shrink-0 xl:w-60"
              >
                <SearchField
                  size="sm"
                  label="Search"
                  placeholder="Search apps"
                  value={query}
                  onChange={setQuery}
                />
              </div>
            </div>
            <TabPanel
              id={category}
              className="mt-4 rounded-none bg-transparent p-0 shadow-none ring-0"
            >
              {shown.length === 0 ? (
                <EmptyState className="bg-card py-12">
                  <EmptyStateIcon>
                    <PlugsConnectedIcon aria-hidden="true" />
                  </EmptyStateIcon>
                  <EmptyStateTitle as="h2">
                    No apps match your search
                  </EmptyStateTitle>
                  <EmptyStateDescription>
                    Try a different name or show all categories.
                  </EmptyStateDescription>
                  <EmptyStateActions>
                    <Button variant="outline" size="sm" onPress={clearSearch}>
                      Clear search
                    </Button>
                  </EmptyStateActions>
                </EmptyState>
              ) : (
                <GridList
                  aria-label="Apps"
                  className="grid gap-3 border-0 bg-transparent p-0 shadow-none sm:grid-cols-2"
                >
                  {shown.map((app) => (
                    <GridListItem
                      key={app.id}
                      id={app.id}
                      textValue={app.name}
                      className="flex-col items-stretch gap-0 rounded-xl border border-border bg-card p-4 shadow-[var(--shadow-card)]"
                    >
                      <div className="flex min-w-0 items-start gap-3">
                        <span
                          aria-hidden="true"
                          className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted text-foreground ring-1 ring-border/60"
                        >
                          <app.icon size={20} />
                        </span>
                        <div className="min-w-0 flex-1">
                          <div className="flex flex-wrap items-center gap-x-2 gap-y-1">
                            <p className="truncate text-[15px] font-semibold">
                              {app.name}
                            </p>
                            {app.beta && (
                              <Badge
                                variant="accent"
                                className="min-h-5 py-0 text-[11px]"
                              >
                                Beta
                              </Badge>
                            )}
                            {app.needsAttention && (
                              <Badge
                                variant="warning"
                                className="min-h-5 py-0 text-[11px]"
                              >
                                Sign in
                              </Badge>
                            )}
                          </div>
                          <p className="mt-0.5 truncate text-xs text-muted-foreground">
                            {app.tagline}
                          </p>
                        </div>
                        <div className="shrink-0">
                          <Switch
                            aria-label={`${app.connected ? "Disconnect" : "Connect"} ${app.name}`}
                            checked={app.connected}
                            onCheckedChange={(connected) =>
                              setConnected(app.id, connected)
                            }
                          />
                        </div>
                      </div>
                      <div className="mt-3 flex items-center justify-between gap-2 border-t border-border/60 pt-3">
                        <span className="text-xs text-muted-foreground">
                          {app.permissions.length}{" "}
                          {app.permissions.length === 1
                            ? "permission"
                            : "permissions"}
                        </span>
                        <Button
                          variant="minimal"
                          size="xs"
                          aria-label={`Details for ${app.name}`}
                          onPress={() => {
                            setSheetId(app.id);
                            setSheetOpen(true);
                          }}
                        >
                          Details
                          <CaretRightIcon size={12} aria-hidden="true" />
                        </Button>
                      </div>
                    </GridListItem>
                  ))}
                </GridList>
              )}
            </TabPanel>
          </Tabs>
        </div>
      </div>

      <Sheet
        isOpen={sheetOpen}
        onOpenChange={setSheetOpen}
        position="right"
        size="md"
      >
        {sheetApp && (
          <>
            <SheetHeader>
              <div className="flex min-w-0 items-start gap-3">
                <span
                  aria-hidden="true"
                  className="grid size-10 shrink-0 place-items-center rounded-xl bg-muted text-foreground ring-1 ring-border/60"
                >
                  <sheetApp.icon size={20} />
                </span>
                <div className="min-w-0">
                  <SheetTitle level={2}>{sheetApp.name}</SheetTitle>
                  <p className="text-sm text-muted-foreground">
                    {sheetApp.publisher}
                  </p>
                </div>
              </div>
              <SheetClose />
            </SheetHeader>
            <SheetBody className="grid content-start gap-5">
              <div className="flex flex-wrap items-center gap-2">
                <Badge variant="outline">
                  {categoryLabel(sheetApp.category)}
                </Badge>
                <Badge
                  variant={sheetApp.connected ? "success" : "neutral"}
                  dot={sheetApp.connected}
                >
                  {sheetApp.connected ? "Connected" : "Not connected"}
                </Badge>
                {sheetApp.beta && <Badge variant="accent">Beta</Badge>}
              </div>
              <SheetDescription>{sheetApp.description}</SheetDescription>
              {sheetApp.needsAttention && (
                <Alert
                  variant="warning"
                  title="Sign in again"
                  action={
                    <Button
                      size="sm"
                      variant="outline"
                      onPress={() => reconnect(sheetApp.id)}
                    >
                      Reconnect
                    </Button>
                  }
                >
                  The Figma token ended on Oct 30, 2026.
                </Alert>
              )}
              <div>
                <h3 className="text-sm font-semibold">Permissions</h3>
                <ul className="mt-2 grid gap-2">
                  {sheetApp.permissions.map((permission) => (
                    <li
                      key={permission}
                      className="flex min-w-0 items-start gap-2 text-sm"
                    >
                      <CheckIcon
                        size={16}
                        aria-hidden="true"
                        className="mt-1 shrink-0 text-success"
                      />
                      <span className="min-w-0">{permission}</span>
                    </li>
                  ))}
                </ul>
              </div>
              <DescriptionList>
                <DescriptionTerm>Last sync</DescriptionTerm>
                <DescriptionDetail>
                  {sheetApp.connected ? sheetApp.lastSync : "Never"}
                </DescriptionDetail>
                {sheetApp.connected && sheetApp.connectedBy && (
                  <>
                    <DescriptionTerm>Connected by</DescriptionTerm>
                    <DescriptionDetail>
                      {sheetApp.connectedBy}
                    </DescriptionDetail>
                    <DescriptionTerm>Connected on</DescriptionTerm>
                    <DescriptionDetail>
                      {sheetApp.connectedOn}
                    </DescriptionDetail>
                  </>
                )}
              </DescriptionList>
            </SheetBody>
            <SheetFooter>
              {sheetApp.connected ? (
                <Button
                  size="sm"
                  variant="outline"
                  className="border-destructive/40 text-destructive hover:bg-destructive/10 hover:text-destructive"
                  onPress={() => setConnected(sheetApp.id, false)}
                >
                  Disconnect
                </Button>
              ) : (
                <Button
                  size="sm"
                  onPress={() => setConnected(sheetApp.id, true)}
                >
                  Connect
                </Button>
              )}
              <SheetClose variant="outline" size="sm">
                Done
              </SheetClose>
            </SheetFooter>
          </>
        )}
      </Sheet>
    </SettingsShell>
  );
}

import { IntegrationsSettings } from "./integrations-settings";

export const metadata = {
  title: "Connected apps",
  description: "App directory with categories, connections, and access review.",
};

export default function IntegrationsPage() {
  return <IntegrationsSettings />;
}

"use client";

import {
  KeyIcon,
  PaletteIcon,
  PlugsConnectedIcon,
  ShieldCheckIcon,
} from "@phosphor-icons/react";
import type { ReactNode } from "react";
import { Avatar } from "../../../components/vip-ui/avatar";
import { Badge } from "../../../components/vip-ui/badge";
import { cn } from "../../../components/vip-ui/utils";

const groups = [
  {
    title: "Account",
    items: [
      {
        id: "security",
        label: "Security",
        href: "/blocks/security-01",
        icon: ShieldCheckIcon,
      },
      {
        id: "appearance",
        label: "Appearance",
        href: "/blocks/appearance-01",
        icon: PaletteIcon,
      },
    ],
  },
  {
    title: "Workspace",
    items: [
      {
        id: "api-keys",
        label: "API keys",
        href: "/blocks/api-keys-01",
        icon: KeyIcon,
      },
      {
        id: "integrations",
        label: "Integrations",
        href: "/blocks/integrations-01",
        icon: PlugsConnectedIcon,
      },
    ],
  },
];

const items = groups.flatMap((group) => group.items);

export type SettingsSection =
  | "security"
  | "appearance"
  | "api-keys"
  | "integrations";

interface SettingsShellProps {
  current: SettingsSection;
  title: string;
  description: string;
  actions?: ReactNode;
  children: ReactNode;
}

export function SettingsShell({
  current,
  title,
  description,
  actions,
  children,
}: SettingsShellProps) {
  return (
    <div className="min-h-svh bg-muted/30">
      <header className="sticky top-0 z-30 border-b border-border/70 bg-background/85 backdrop-blur-md">
        <div className="mx-auto flex h-16 w-full max-w-[1280px] items-center gap-3 px-6 lg:px-8">
          <span
            aria-hidden="true"
            className="grid size-9 shrink-0 place-items-center rounded-xl bg-primary text-base font-bold text-primary-foreground shadow-[var(--shadow-card)]"
          >
            K
          </span>
          <div className="min-w-0">
            <p className="truncate text-sm font-semibold">Kestrel</p>
            <p className="truncate text-xs text-muted-foreground">Settings</p>
          </div>
          <div className="ms-auto flex min-w-0 items-center gap-3">
            <Badge variant="outline" className="max-sm:hidden">
              Pro plan
            </Badge>
            <div className="hidden min-w-0 text-end sm:block">
              <p className="truncate text-sm font-medium leading-5">
                Nadia Okafor
              </p>
              <p className="truncate text-xs leading-4 text-muted-foreground">
                Workspace admin
              </p>
            </div>
            <Avatar name="Nadia Okafor" />
          </div>
        </div>
      </header>
      <div className="mx-auto grid w-full max-w-[1280px] gap-6 px-6 py-6 md:py-8 lg:grid-cols-[15rem_minmax(0,1fr)] lg:items-start lg:gap-10 lg:px-8">
        <aside className="min-w-0 lg:sticky lg:top-[5.5rem]">
          <nav aria-label="Settings">
            <div className="grid grid-cols-2 gap-1.5 sm:grid-cols-4 lg:hidden">
              {items.map((item) => (
                <SettingsLink
                  key={item.id}
                  item={item}
                  active={item.id === current}
                  pill
                />
              ))}
            </div>
            <div className="hidden lg:grid lg:gap-6">
              {groups.map((group) => (
                <div key={group.title} className="min-w-0">
                  <p className="px-2.5 pb-1.5 text-[11px] font-semibold tracking-[0.09em] text-muted-foreground uppercase">
                    {group.title}
                  </p>
                  <ul className="grid gap-0.5">
                    {group.items.map((item) => (
                      <li key={item.id}>
                        <SettingsLink
                          item={item}
                          active={item.id === current}
                        />
                      </li>
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </nav>
          <div className="mt-7 hidden rounded-xl bg-card p-3.5 shadow-[var(--shadow-card)] ring-1 ring-border/70 lg:block">
            <p className="text-xs font-medium text-muted-foreground">
              Workspace
            </p>
            <p className="mt-2 truncate text-sm font-semibold">
              Kestrel Insights
            </p>
            <p className="truncate text-xs text-muted-foreground">
              12 members · 3 environments
            </p>
          </div>
        </aside>
        <main className="min-w-0">
          <div className="mb-6 flex flex-wrap items-end justify-between gap-4">
            <div className="min-w-0">
              <h1 className="text-2xl font-semibold tracking-[-0.04em]">
                {title}
              </h1>
              <p className="mt-1 max-w-2xl text-sm leading-6 text-muted-foreground">
                {description}
              </p>
            </div>
            {actions}
          </div>
          {children}
        </main>
      </div>
    </div>
  );
}

function SettingsLink({
  item,
  active,
  pill = false,
}: {
  item: (typeof items)[number];
  active: boolean;
  pill?: boolean;
}) {
  return (
    <a
      href={item.href}
      aria-current={active ? "page" : undefined}
      className={cn(
        "flex min-h-10 min-w-0 items-center gap-2.5 rounded-lg px-3 text-sm font-medium outline-offset-2 outline-transparent transition-[color,background-color] duration-150 ease-out-quint focus-visible:outline-2 focus-visible:outline-ring",
        pill
          ? "shrink-0 border border-border bg-card shadow-[var(--shadow-card)]"
          : "w-full",
        active
          ? "bg-accent text-accent-foreground"
          : "text-muted-foreground hover:bg-muted/70 hover:text-foreground",
      )}
    >
      <item.icon
        size={17}
        weight={active ? "fill" : "regular"}
        aria-hidden="true"
      />
      <span className="truncate">{item.label}</span>
    </a>
  );
}
